from __future__ import annotations

import re
from collections import defaultdict


def _norm(text: str) -> str:
    return " ".join(text.split()).casefold()


def _skeleton(text: str) -> str:
    text = _norm(text)
    text = re.sub(r"\b\d+[\d.,]*\b", "<n>", text)
    text = re.sub(r"\b(?:frau|herr)\s+[a-zäöüß-]+\b", "<name>", text)
    text = re.sub(r"\b(?:montag|dienstag|mittwoch|donnerstag|freitag|samstag|sonntag)\b", "<tag>", text)
    return text


def _round_robin_unique(items, target):
    by_topic = defaultdict(list)
    for q in items:
        by_topic[q.topic].append(q)
    topics = sorted(by_topic)
    idx = {t: 0 for t in topics}
    out = []
    seen_pc = set()
    seen_opts = set()
    while len(out) < target:
        progressed = False
        for t in topics:
            bucket = by_topic[t]
            while idx[t] < len(bucket):
                q = bucket[idx[t]]
                idx[t] += 1
                pc = (_norm(q.prompt), _norm(q.correct))
                if pc in seen_pc:
                    continue
                if q.kind == "choice":
                    sig = tuple(sorted(_norm(x) for x in (q.options or [])))
                    if sig in seen_opts:
                        continue
                    seen_opts.add(sig)
                seen_pc.add(pc)
                out.append(q)
                progressed = True
                break
            if len(out) >= target:
                break
        if not progressed:
            break
    return out


def build_quality_pool(existing_questions, Question, choice, number, money):
    """Return exactly 3,000 active questions: 200 per category and level.

    Existing, already diverse questions are reused for accounting, business processes
    and correspondence. German and office organization receive fresh level-specific
    banks because those were the areas where cross-level repetition was most obvious.
    """
    categories = [
        "Rechnungswesen",
        "Geschäftsprozesse",
        "Deutsch & Rechtschreibung",
        "Schriftverkehr",
        "Büroorganisation",
    ]
    levels = ["Anfänger", "Fortgeschritten", "Experte"]

    active = []
    # Reuse the strongest portions of the existing pool for three categories.
    for cat in ["Rechnungswesen", "Geschäftsprozesse", "Schriftverkehr"]:
        for lvl in levels:
            candidates = [q for q in existing_questions if q.category == cat and q.level == lvl]
            # Prefer expanded, varied material, then fill with curated legacy/base material.
            candidates.sort(key=lambda q: (0 if q.id.startswith("x_") else 1, q.topic, q.id))
            picked = _round_robin_unique(candidates, 200)
            if len(picked) != 200:
                raise RuntimeError(f"Could not select 200 unique tasks for {cat}/{lvl}: {len(picked)}")
            active.extend(picked)

    active.extend(_build_german(choice))
    active.extend(_build_office(choice))

    if len(active) != 3000:
        raise RuntimeError(f"Quality pool size {len(active)} != 3000")
    return active


def _build_german(choice):
    out = []
    out += _german_beginner(choice)
    out += _german_intermediate(choice)
    out += _german_expert(choice)
    return out


def _make_choice(choice, qid, topic, level, prompt, correct, wrong, explanation, hint):
    return choice(qid, "Deutsch & Rechtschreibung", topic, level, prompt, correct, wrong, explanation, hint)


